#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/stat.h>
#include <unistd.h>

int main(int argc, char *argv[]) {
    char *buf;
    ssize_t nbytes, bufsiz;
    struct stat sb;
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <pathname>\n", argv[0]);
        exit(EXIT_FAILURE);
    }
    if (lstat(argv[1], &sb) == -1) {
        perror("lstat");
        exit(EXIT_FAILURE);
    }
    bufsiz = sb.st_size + 1;
    if (sb.st_size == 0) bufsiz = PATH_MAX;
    buf = malloc(bufsiz);
    if (buf == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    nbytes = readlink(argv[1], buf, bufsiz);
    if (nbytes == -1) {
        perror("readlink");
        exit(EXIT_FAILURE);
    }
    printf("'%s' points to '%.*s'\n", argv[1], (int) nbytes, buf);
    if (nbytes == bufsiz) printf("(Returned buffer may have been truncated)\n");
    free(buf);
    exit(EXIT_SUCCESS);
}
